import{n as e}from"./rolldown-runtime-2d059c5e81f4.js";import{DDt as t,EDt as n,ODt as r}from"./app-shared-61271c39e3c5.js";var i,a,o;function s(){return(s=e((()=>{r(),i={kind:`native_action`,id:`writing_style`,taskKey:`writing_style`,category:`skill`,source:`static`,label:n({id:`chatgpt.tpp.onboarding.mock_setup.writing_style.label`,defaultMessage:`Learn my writing style`,description:`Title on a personalization card in the mock ChatGPT Work setup experience. Selecting it starts an internal demo skill that learns how the end user writes. Short card label.`}),description:n({id:`chatgpt.tpp.onboarding.mock_setup.writing_style.description`,defaultMessage:`Get drafts that sound like you`,description:`Short supporting sentence below the Learn my writing style fallback task in ChatGPT Work onboarding tiles and the showcase. Explains to end users that learning their writing style helps produce text drafts in their own voice; sound refers to writing tone, not audio. Keep concise for a compact tile. No placeholders.`})},a=t({personalWebsiteLabel:{id:`chatgpt.tpp.onboarding.starter.personal_website.label`,defaultMessage:`Build a personal website`,description:`Title on a starter task card in the ChatGPT Work onboarding conversation. Selecting it starts a Work conversation that creates, hosts, and maintains a personal website tailored to the user. Short card label.`},personalWebsiteDescription:{id:`chatgpt.tpp.onboarding.starter.personal_website.description`,defaultMessage:`Create a personalized website based on what you have shared`,description:`Short supporting description below the personal website fallback task on the See what Work can do showcase during ChatGPT Work onboarding. It tells end users that ChatGPT can create a personalized website using information they have shared. Keep it to one concise sentence. No placeholders.`},personalWebsitePrompt:{id:`chatgpt.tpp.onboarding.starter.personal_website.prompt`,defaultMessage:`Based on everything you know about me and what we’ve discussed in past conversations, choose the most useful subject for a personal website. If there isn’t enough context to choose honestly, ask me one focused question about what the site should be for. Then design, build, and host it for me. Make confident choices about the content, structure, and visual style you think I’ll like best, and start creating it now.`,description:`Prompt submitted when the user selects the personal website starter task in the ChatGPT Work onboarding conversation. It asks ChatGPT to choose a useful website subject from context already available in past conversations, then design, build, and host the site immediately. It must not invent personal details or claim access to unavailable context.`},manageInboxLabel:{id:`chatgpt.tpp.onboarding.starter.manage_inbox.label`,defaultMessage:`Help manage my inbox`,description:`Title on a starter task card in the ChatGPT Work onboarding conversation. Selecting it starts a Work conversation that learns the user's email style, creates a reusable skill, and prepares important unanswered email each morning. Short card label.`},manageInboxDescription:{id:`chatgpt.tpp.onboarding.starter.manage_inbox.description`,defaultMessage:`Learn your writing style and help draft replies to unread emails`,description:`Short supporting description below the inbox-management fallback task on the See what Work can do showcase during ChatGPT Work onboarding. It tells end users that ChatGPT can learn their writing style and help prepare replies to unread email. Keep it to one concise sentence. No placeholders.`},manageInboxPrompt:{id:`chatgpt.tpp.onboarding.starter.manage_inbox.prompt`,defaultMessage:`Use my connected email app. If I haven’t connected one, ask which email provider I use and help me connect it before continuing. Then review the emails I’ve sent over the last three months and learn how my writing changes for different people and situations. Create a reusable email-writing skill that captures those styles, patterns, and preferences. Set up a daily automation that reviews my unread emails and drafts a response to each one in the appropriate style. Never send an email without my explicit confirmation.`,description:`Prompt submitted when the user selects the inbox management starter task in the ChatGPT Work onboarding conversation. It asks ChatGPT to use or help connect the user's preferred email provider, study three months of sent email to learn how the user writes to different people, create a reusable email-writing skill, and create a daily automation that drafts replies to unread email. It explicitly prohibits sending email without confirmation.`},repeatableWorkLabel:{id:`chatgpt.tpp.onboarding.skill_fallback.repeatable_work.label`,defaultMessage:`Make my work repeatable`,description:`Short title on a fallback task card in ChatGPT Work onboarding v3 tiles and the See what Work can do showcase. Selecting it asks ChatGPT to identify a recurring workflow and, after the end user confirms it, save it as a reusable skill. Keep concise for a compact card. No placeholders or markup.`},repeatableWorkDescription:{id:`chatgpt.tpp.onboarding.skill_fallback.repeatable_work.description`,defaultMessage:`Turn recurring tasks into skills you can run`,description:`Short supporting sentence below the repeatable-work fallback task in ChatGPT Work onboarding v3 tiles and the See what Work can do showcase. It tells end users that ChatGPT can save recurring workflows as reusable skills they can invoke later. Keep concise for a compact card. No placeholders or markup.`},repeatableWorkPrompt:{id:`chatgpt.tpp.onboarding.skill_fallback.repeatable_work.prompt.user_request`,defaultMessage:`Find a workflow I repeat and turn it into a reusable skill`,description:`Short user-visible prompt submitted when an end user selects the repeatable-work fallback task in ChatGPT Work onboarding v3 tiles or the See what Work can do showcase. Hidden developer instructions tell ChatGPT to find a recurring workflow, confirm it with the user, save it as a skill, and offer three future uses without applying it yet. No placeholders or markup.`},personalizedPresentationLabel:{id:`chatgpt.tpp.onboarding.starter.personalized_presentation.label`,defaultMessage:`Make a presentation for me`,description:`Title on a starter task card in the ChatGPT Work onboarding conversation. Selecting it starts a Work conversation that chooses a useful topic from the user's past conversations and creates a polished slide presentation. Short card label.`},personalizedPresentationDescription:{id:`chatgpt.tpp.onboarding.starter.personalized_presentation.description`,defaultMessage:`Create a polished slide presentation based on your past conversations`,description:`Short supporting description below the presentation fallback task on the See what Work can do showcase during ChatGPT Work onboarding. It tells end users that ChatGPT can use their past conversations to create a polished slide presentation. Keep it to one concise sentence. No placeholders.`},personalizedPresentationPrompt:{id:`chatgpt.tpp.onboarding.starter.personalized_presentation.prompt`,defaultMessage:`Review our past conversations and choose the topic that would be most useful to turn into a polished slide presentation for me right now. If there isn’t enough context to choose honestly, ask me one focused question about the subject. Then pull together the relevant context, decide on a strong story and structure, write the content, and create the complete presentation with useful visuals. Make confident choices and start creating it now. When it’s ready, give me the finished file and a brief note explaining what you chose and why.`,description:`Prompt submitted when the user selects the presentation starter task in the ChatGPT Work onboarding conversation. It asks ChatGPT to choose a useful topic grounded in the user's past conversations, create a complete polished slide presentation immediately, and provide the finished file with a short explanation. It must not invent a topic or claim context that is unavailable.`}}),o=[{kind:`prompt`,category:`website`,source:`static`,id:`build-and-deploy-website`,label:a.personalWebsiteLabel,description:a.personalWebsiteDescription,prompt:a.personalWebsitePrompt,instructionProfile:`website`,thinkingEffort:`xhigh`},{kind:`prompt`,category:`email`,source:`static`,id:`learn-email-style`,label:a.manageInboxLabel,description:a.manageInboxDescription,prompt:a.manageInboxPrompt,instructionProfile:`email_messaging`,thinkingEffort:`min`},{kind:`prompt`,category:`skill`,source:`static`,taskKey:`repeatable_work`,id:`make-work-repeatable`,label:a.repeatableWorkLabel,description:a.repeatableWorkDescription,prompt:a.repeatableWorkPrompt,developerInstructions:"Look across my past conversations, including older chats, for a workflow I repeat that spans apps, websites, or files. Use only context you can actually access; never invent conversations or examples. If there is not enough evidence to identify a recurring workflow, first call `request_user_input` to ask one focused question about a workflow I repeat and a real example, then wait for my answer before proposing one. Once a workflow is supported by the available history or my answer, show a section titled ‘Workflow I found’ with a plain-language description of the workflow, real supporting examples (2–3 when available), and the background and decisions the skill would preserve. Do not create the skill, call Skill Creator, or continue to any next step in that response. After the evidence is visible, stop and call `request_user_input` to ask: ‘Is this workflow accurate, and should I turn it into a skill?’ Offer two choices: ‘Yes, create it’ and ‘No, revise it’. Do not ask for confirmation in ordinary chat text. Wait for the tool response before doing anything else.\n\nOnly after I explicitly confirm, create it as a reusable skill. Give it a descriptive lowercase kebab-case name in the `your-new-skill` format. Do not stop after saving it. In the same response, show a section titled ‘Try it next’ with a numbered list of exactly 3 concrete requests I could use the skill for in future work. Do not invoke or apply the skill yet. End by asking whether I would like to try one of those three examples, and which one.",instructionProfile:`skill`,thinkingEffort:`min`},{kind:`prompt`,category:`artifact`,source:`static`,id:`make-personalized-presentation`,label:a.personalizedPresentationLabel,description:a.personalizedPresentationDescription,prompt:a.personalizedPresentationPrompt,instructionProfile:`artifact`,thinkingEffort:`xhigh`}]})))()}export{s as n,i as r,o as t};
